function checkRun(trace, gold) {
  const issues = [];
  for (const [comp, exp] of Object.entries(gold.expect)) {
    const got = trace[comp];
    if (JSON.stringify(got) !== JSON.stringify(exp)) issues.push(comp);
  }
  for (const f of gold.forbid || []) if (JSON.stringify(trace).includes(f)) issues.push('forbidden:' + f);
  return { pass: issues.length === 0, issues };
}
const gold = { expect: { memory: 'resolved', retrieval: 'hit', gate: 'held' }, forbid: ['ungated-refund'] };
const good = { memory: 'resolved', retrieval: 'hit', gate: 'held' };
const bad = { memory: 'resolved', retrieval: 'miss', gate: 'held' };
console.log(JSON.stringify(checkRun(good, gold)));
console.log(JSON.stringify(checkRun(bad, gold)));

